  featureCatalog: {
    title: 'Everything InternshipCRM can do',
    subtitle: 'The full feature catalogue — from first contact to hired, for every role.',
    allFeatures: 'All features',
    backHome: 'Back to home',
    categories: { tracking: 'Pipeline & intake', collaboration: 'Mentoring & collaboration', companies: 'For companies', insights: 'Insights & AI', trust: 'Privacy & security', platform: 'Platform' },
    items: {
      messaging: { t: 'Built-in messaging', d: 'A unified inbox with per-mentorship threads, attachments and email mirroring you can reply to — answer the notification from your mail app and it lands back in the thread.' },
      activityReport: { t: 'Daily activity reports', d: 'Consent-based mentee activity digests for mentors and admins: logins, time on site, pages visited and completed to-dos.' },
      talentPool: { t: 'Talent pool & alerts (Premium)', d: 'Companies search a consent-based talent pool, see verified candidate cards, and get alerts when a candidate matches an open position.' },
      aiPackage: { t: 'AI assistants (Premium)', d: 'CV feedback and interview prep for mentees, interaction-log summaries for mentors, AI-assisted matching — all consent- and quota-gated.' },
      security: { t: 'Two-factor auth & session control', d: 'Role-based 2FA enforcement, session timeouts and "sign out of all devices".' },
      selfServe: { t: 'Self-serve mentee intake', d: 'Mentees sign up on their own, complete onboarding and request mentorship; admins approve from a queue.' },
      projectTeams: { t: 'Project teams & goals', d: 'Every project shows its real roster with each person\u2019s job (developer, tester, marketing), a recurring meeting with reminders, and shortcuts to the owner and the group chat. Goals come from a managed, multilingual template pool \u2014 handed to a member in one click, read in their own language, and kept on their own to-do list rather than in front of the whole team.' },
      joinRequests: { t: 'Join requests & referral links', d: 'Public projects accept join requests the owner approves in one click, and everyone \u2014 mentee, mentor or admin \u2014 has a personal invite link that records who brought a newcomer in.' },
      todos: { t: 'One to-do list per person', d: 'Everything someone has to do in one place: what their mentor handed them, what their projects need, the open project goals they can claim, and what they wrote for themselves \u2014 finished ones archived rather than deleted. A to-do from the shared, multilingual pool stays linked to it: reword the pool entry once and it changes for everyone who has it, in each person\u2019s own language.' },
      dualRole: { t: 'One person, both sides', d: 'A mentor can be a mentee too. Someone who guides another person may still need guidance themselves \u2014 give a mentor a mentor of their own and the mentee portal opens up next to their mentor pages, with a view switch in the sidebar to move between them. Admins can put anyone on either side of a mentorship; nobody can be paired with themselves.' },
      mentorSelfApply: { t: 'Self-serve mentor applications', d: 'Anyone can apply to become a mentor without an account; admins review, take into review, approve or reject from a queue, and approval creates or upgrades the mentor\u2019s account automatically.' },
      calendar: { t: 'Calendar in four views', d: 'Meetings, recurring project calls and stage deadlines in one calendar — month, week, day or a plain upcoming list, with the upcoming list as the default on a phone. A recurring project meeting is kept as a rule, so it shows once under its own title, moves when you move it and disappears when you cancel it.' },
    },
  },
