  consent: { section: 'Gizlilik ve onay', intro: 'İsteğe bağlı veri işlemeyi sen kontrol edersin. Bunlar varsayılan olarak kapalıdır ve istediğin zaman değiştirebilirsin.', items: { aiCvParsing: { title: 'AI destekli CV okuma', desc: 'Profil alanlarını daha doğru önermek için CV metninin bir AI sağlayıcısına gönderilmesine izin ver. Bu olmadan yalnızca cihaz üzerinde ayrıştırma kullanılır. CV dosyan asla paylaşılmaz; yalnızca öneri istediğinde çıkarılan metin gönderilir.' }, activityTracking: { title: 'Ayrıntılı etkinlik takibi', desc: 'Hangi sayfaları ziyaret ettiğinin ve ne kadar süre geçirdiğinin kaydedilmesine izin ver; böylece mentorun ve yöneticiler ayrıntılı bir etkinlik raporu görebilir. Varsayılan olarak kapalıdır; yalnızca site içi gezinme kaydedilir — tuş vuruşları veya sayfa içeriği asla.' }, talentPoolVisibility: { title: 'Şirketlere görünürlük (yetenek havuzu)', desc: 'Partner şirketlerin profilini yetenek havuzu aramasında bulmasına ve açık pozisyonları için eşleşme bildirimi almasına izin ver. Şirketler herkese açık profilini görür (ad, üniversite, yetenekler, hedef pozisyon) — e-postanı veya telefonunu asla. Varsayılan olarak kapalıdır; istediğin an geri çekebilirsin ve şirket aramasından anında çıkarsın.' }, aiInteractionSummary: { title: 'Etkileşim kayıtlarının AI özeti', desc: 'Mentörünün, mentorluğunla ilgili tuttuğu etkileşim kayıtlarının AI özetini oluşturmasına izin ver. AI sağlayıcısına yalnızca kayıt metni gönderilir — dosyalar veya iletişim bilgileri asla. Varsayılan olarak kapalıdır.' } } },
