  consent: { section: 'Datenschutz & Einwilligung', intro: 'Du steuerst die optionale Datenverarbeitung. Diese ist standardmäßig aus und jederzeit änderbar.', items: { aiCvParsing: { title: 'KI-gestütztes Lesen des Lebenslaufs', desc: 'Erlaube, den Text deines Lebenslaufs an einen KI-Anbieter zu senden, um Profilfelder genauer vorzuschlagen. Ohne dies wird nur die Verarbeitung auf dem Gerät genutzt. Deine Lebenslauf-Datei wird nie geteilt; nur der extrahierte Text wird gesendet, wenn du einen Vorschlag auslöst.' }, activityTracking: { title: 'Detailliertes Aktivitäts-Tracking', desc: 'Erlaube die Aufzeichnung, welche Seiten du besuchst und wie lange, damit dein Mentor und Admins einen detaillierten Aktivitätsbericht sehen können. Standardmäßig aus; nur die Navigation innerhalb der App wird erfasst — niemals Tastatureingaben oder Seiteninhalte.' }, talentPoolVisibility: { title: 'Sichtbarkeit für Unternehmen (Talent-Pool)', desc: 'Erlaube Partnerunternehmen, dein Profil in der Talent-Pool-Suche zu finden und Match-Benachrichtigungen für ihre offenen Stellen zu erhalten. Sie sehen dein öffentliches Profil (Name, Universität, Fähigkeiten, Zielposition) — nie deine E-Mail oder Telefonnummer. Standardmäßig aus; du kannst jederzeit widerrufen und verschwindest sofort aus der Unternehmenssuche.' }, aiInteractionSummary: { title: 'KI-Zusammenfassung der Interaktionsprotokolle', desc: 'Erlaube deinem Mentor, eine KI-Zusammenfassung des Interaktionsprotokolls deines Mentorings zu erstellen. Nur der Protokolltext wird an den KI-Anbieter gesendet — nie Dateien oder Kontaktdaten. Standardmäßig aus.' } } },
