    items: {
      messaging: { t: 'Integrierte Nachrichten', d: 'Ein zentraler Posteingang mit Threads pro Mentoring, Anhängen und beantwortbarer E-Mail-Spiegelung — antworte aus deinem Mailprogramm, und die Antwort landet im Thread.' },
      activityReport: { t: 'Tägliche Aktivitätsberichte', d: 'Einwilligungsbasierte Mentee-Aktivitätsübersichten für Mentoren und Admins: Logins, Verweildauer, besuchte Seiten und erledigte To-dos.' },
      talentPool: { t: 'Talent-Pool & Benachrichtigungen (Premium)', d: 'Unternehmen durchsuchen einen einwilligungsbasierten Talent-Pool, sehen verifizierte Kandidatenkarten und werden bei passenden Kandidaten benachrichtigt.' },
      aiPackage: { t: 'KI-Assistenten (Premium)', d: 'Lebenslauf-Feedback und Interviewvorbereitung für Mentees, Interaktionszusammenfassungen für Mentoren, KI-gestütztes Matching — alles einwilligungs- und kontingentgesteuert.' },
      security: { t: 'Zwei-Faktor-Auth & Sitzungskontrolle', d: 'Rollenbasierte 2FA-Durchsetzung, Sitzungs-Timeouts und „Auf allen Geräten abmelden".' },
      selfServe: { t: 'Self-Service-Mentee-Aufnahme', d: 'Mentees registrieren sich selbst, durchlaufen das Onboarding und fragen Mentoring an; Admins genehmigen aus einer Warteschlange.' },
      projectTeams: { t: 'Projektteams & Ziele', d: 'Jedes Projekt zeigt sein echtes Team samt Aufgabe (Entwicklung, Test, Marketing), ein wiederkehrendes Treffen mit Erinnerungen sowie Shortcuts zum Owner und zum Gruppenchat. Ziele kommen aus einem verwalteten, mehrsprachigen Vorlagenpool: mit einem Klick vergeben, in der eigenen Sprache gelesen und auf der Aufgabenliste der Person statt vor dem ganzen Team.' },
      joinRequests: { t: 'Beitrittsanfragen & Empfehlungslinks', d: 'Öffentliche Projekte nehmen Beitrittsanfragen an, die der Owner mit einem Klick freigibt; und alle \u2014 Mentee, Mentor oder Admin \u2014 haben einen persönlichen Einladungslink, der festhält, wer jemanden gebracht hat.' },
      todos: { t: 'Eine Aufgabenliste pro Person', d: 'Alles, was jemand zu tun hat, an einem Ort: was Mentorin oder Mentor gegeben hat, was die Projekte brauchen, offene Projektziele zum Übernehmen und eigene Notizen \u2014 Erledigtes wird archiviert, nicht gelöscht. Eine Aufgabe aus dem gemeinsamen, mehrsprachigen Pool bleibt damit verknüpft: einmal neu formuliert, ändert sie sich für alle, die sie haben \u2014 jeweils in deren Sprache.' },
      dualRole: { t: 'Eine Person, beide Seiten', d: 'Ein Mentor kann auch Mentee sein. Wer andere begleitet, braucht manchmal selbst Begleitung \u2014 bekommt ein Mentor eine eigene Mentorin oder einen eigenen Mentor, \u00f6ffnet sich neben den Mentoren-Seiten das Mentee-Portal, mit einem Ansichtsschalter in der Seitenleiste zum Wechseln. Admins k\u00f6nnen beide Seiten einer Mentorschaft frei besetzen; niemand l\u00e4sst sich mit sich selbst verkn\u00fcpfen.' },
      mentorSelfApply: { t: 'Self-Service-Mentor-Bewerbungen', d: 'Jeder kann sich ohne Konto als Mentor bewerben; Admins prüfen die Warteschlange, starten die Prüfung, genehmigen oder lehnen ab — bei Genehmigung wird das Mentor-Konto automatisch erstellt oder hochgestuft.' },
      calendar: { t: 'Kalender in vier Ansichten', d: 'Meetings, wiederkehrende Projekt-Calls und Phasenfristen in einem Kalender — Monat, Woche, Tag oder eine schlichte Demnächst-Liste, auf dem Handy standardmäßig die Demnächst-Liste. Ein wiederkehrendes Projekt-Meeting wird als Regel geführt: Es erscheint einmal unter seinem eigenen Titel, wandert mit, wenn du es verschiebst, und verschwindet, wenn du es absagst.' },
    },
