    intro: 'Wir speichern die von dir bereitgestellten Informationen, um Mentorings und Praktika zu verwalten. Dieser Hinweis erklärt, was wir verarbeiten, warum, wer es sehen kann, wie lange wir es aufbewahren und welche Rechte du hast (DSGVO Art. 13–15).',
    controllerTitle: 'Wer ist verantwortlich',
    controllerBody: 'Verantwortlicher ist die Organisation, die diese InternshipCRM-Instanz betreibt. Kontaktdaten des Verantwortlichen und ggf. des Datenschutzbeauftragten (DSB) werden vom Betreiber bereitgestellt — siehe „Kontakt“ unten.',
    purposesTitle: 'Wofür wir deine Daten verwenden',
