    intro: 'Diese Plattform bringt Menschen am Anfang ihrer Laufbahn mit Mentorinnen, Mentoren und Unternehmen zusammen. Das funktioniert nur, wenn sich alle sicher und respektiert fühlen. Diese Regeln gelten gleichermaßen für Mentees, Mentoren, Admins und Unternehmenskontakte.',
